async function jevDecide(state,questions){
  try{
    const r=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({decide:true,state,questions})});
    if(r.ok)return (await r.json()).answers||null;
  }catch(e){}
  return null;
}
/* postura robusta: si el residente no cerró la etiqueta, Jev clasifica el texto */
async function clasificarPostura(q,txt){
  const a=await jevDecide(`Pregunta: ${q}\nRespuesta: ${txt}`,
    {postura:{type:"choice",instructions:"La postura que expresa esta respuesta",
      criteria:{a_favor:"apoya o se inclina a favor",en_contra:"rechaza o se inclina en contra",
                depende:"genuinamente dividida o condicionada"}}});
  return a?.postura?.choice||null;
}
/* sello de humanidad: Jev califica si la mesa sonó a gente de verdad */
async function selloHumano(q,transcript,host){
  const a=await jevDecide(`Tema: ${q}\nConversación:\n`+
    transcript.map(t=>`${t.n}: ${t.t}`).join("\n"),
    {humana:{type:"noul",instructions:"La conversación suena a personas reales distintas (no a un mismo bot repetido): estilos variados, vidas concretas, nada de frases de IA"},
     sustancia:{type:"score",instructions:"Sustancia de los argumentos",
       criteria:["vacía","floja","aceptable","buena","excelente"]}});
  if(!a)return;
  const h=Math.round((a.humana?.noul||0)*100),s=a.sustancia?.score;
  (host||$("#resps")).insertAdjacentHTML("beforeend",
    `<div class="ronda" style="letter-spacing:.08em">SELLO HUMANO · humanidad ${h}% · sustancia ${s?.toFixed(1)??"—"}/4</div>`);
}
